-- Run only on isolated homologation. Every test body rolls back by exception.
BEGIN;
CREATE TEMP TABLE qa_retention_results(result jsonb) ON COMMIT DROP;
DO $qa$ DECLARE rid uuid; actual boolean; detail text; results jsonb:='[]'; BEGIN IF NOT EXISTS(SELECT 1 FROM migration_private.environment WHERE branch_id='br-crimson-mud-bcyk3t3x') THEN RAISE EXCEPTION 'isolated branch required'; END IF; PERFORM set_config('app.user_id','00000000-0000-4000-8000-000000000001',true); BEGIN INSERT INTO public.messages(user_id,type,body) VALUES('00000000-0000-4000-8000-000000000002','dica','QA retention boundary') RETURNING id INTO rid;UPDATE public.messages SET created_at=now()-interval '29 days' WHERE id=rid; PERFORM public.archive_maintenance(); SELECT archived_at IS NOT NULL INTO actual FROM public.messages WHERE id=rid; IF actual IS DISTINCT FROM false THEN RAISE EXCEPTION 'wrong archive boundary'; END IF; RAISE EXCEPTION 'QA_ROLLBACK_OK'; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS detail=MESSAGE_TEXT; results:=results||jsonb_build_array(jsonb_build_object('name','retention/messages/archive-29d','passed',detail='QA_ROLLBACK_OK','error',NULLIF(detail,'QA_ROLLBACK_OK'))); END;
